INSERT INTO "schedule_versions" VALUES('20260623000402',44,'2026-09-26T01:14:18+09:00','2026-07-07',NULL,NULL,NULL,NULL,'2026-08-13','2026-08-14','2026-08-24',NULL,36400,NULL,'{"source": "estkRs", "general": {"rcept_no": "20260623000402", "corp_cls": "K", "corp_code": "01784914", "corp_name": "클로봇", "sbd": "2026년 08월 13일 ~ 2026년 08월 14일", "pymd": "2026년 08월 24일", "sband": "2026년 08월 18일", "asand": "2026년 08월 24일", "asstd": "2026년 07월 07일", "exstk": "-", "exprc": "-", "expd": "-", "rpt_rcpn": "20260604000459"}, "facts": {"underwriting": "잔액인수", "discount": 0.25, "major_holder": {"level": "partial", "pct": 10.0, "initial_pct": 10.0, "held_pct": 70.0, "conflict": false, "evidence": [{"basis": "unknown", "pct": null, "polarity": "unknown", "text": "금번 유상증자를 통해 발행 예정인 주식수는 5,494,500주이며, 당사 최대주주인 김창구 대표이사는 853,833주를 배정 받을 예정입니다. 최대주주 김창구 대표이사는 개인 보유자금 10억원과 미청약 신주인수권증서 매각대금(현재 미정)으로 청약 참여를 계획하고 있습니다.", "rcept_no": "20260623000402", "rcept_dt": "20260623"}, {"basis": "unknown", "pct": null, "polarity": "unknown", "text": "최대주주 김창구 대표이사는 개인 보유자금 10억원과 미청약 신주인수권증서 매각대금(현재 미정)으로 청약 참여를 계획하고 있습니다. 당사는 최대주주 김창구 대표이사의 1) 10억원 및 미청약 신주인수권증서 매각대금 수준의 청약금액, 2) 유상증자, 3) 주식매수선택권 미행사수량의 추후 행사 가능성 등의 이유로 인해 본 공시서류 제출일 전일 현재 최대주주의 지분율 대비 지분율이 하락할 수 있습니다.", "rcept_no": "20260623000402", "rcept_dt": "20260623"}, {"basis": "unknown", "pct": null, "polarity": "unknown", "text": "금번 유상증자를 통해 발행 예정인 주식수는 5,494,500주이며, 당사 최대주주인 김창구 대표이사는 853,833주를 배정 받을 예정입니다. 김창구 대표이사는 보유주식이 상장 당시 설정된 3년의 보호예수에 걸려있어 보유주식을 통한 자금 조달 또한 어려운 상황임에 따라, 개인 보유자금 10억원과 미청약 신주인수권증서 매각대금(현재 미정)으로 청약 참여를 계획하고 있습니다.", "rcept_no": "20260623000402", "rcept_dt": "20260623"}, {"basis": "held", "pct": 70.0, "polarity": "positive", "text": "이에 따라 금번 유상증자 이후 당사 최대주주의 지분율은 13.02%로 본 공시서류 제출일 전일 지분율 대비 -2.52%p 하락할 것으로 예상됩니다. 명확히하면, 김창구 대표이사는 금번 유상증자에서 개인 보유자금 10억원과 신주인수권증서를 매각한 대금으로 청약에 참여할 예정이며, 본 위험에 기재된 ''최대주주 지분율 변동 시뮬레이션 : 유상증자'' 표와 같이 신주인수권증서의 가격을 이론권리락가 와 예정발행가액의 차이로 단순 산출하고 이에 70% 할인된 가액으로 매각을 가정하였을 때 약 10% 청약이 가능합니다.", "rcept_no": "20260623000402", "rcept_dt": "20260623"}, {"basis": "held", "pct": 70.0, "polarity": "positive", "text": "명확히하면, 김창구 대표이사는 금번 유상증자에서 개인 보유자금 10억원과 신주인수권증서를 매각한 대금으로 청약에 참여할 예정이며, 본 위험에 기재된 ''최대주주 지분율 변동 시뮬레이션 : 유상증자'' 표와 같이 신주인수권증서의 가격을 이론권리락가 와 예정발행가액의 차이로 단순 산출하고 이에 70% 할인된 가액으로 매각을 가정하였을 때 약 10% 청약이 가능합니다. 다만, 실제 신주인수권증서 매각에 따라 확보하는 자금이 본 위험에서 산출한 예상가액 대비 하락하거나, 확정발행가액이 예정발행가액보다 상승할 경우 최대주주 김창구 대표이사의 청약률은 10% 보다 하락할 수 있으니 투자자께서는 이 점 유의하시기 바랍니다.", "rcept_no": "20260623000402", "rcept_dt": "20260623"}, {"basis": "initial", "pct": 10.0, "polarity": "positive", "text": "268,385 14.00% - - - - - - - 주) 최대주주 및 특수관계인의 주식수는 주식매수선택권 행사 등으로 변동될 수 있습니다. 출처: 당사 제공 당사 최대주주인 김창구 대표이사는 상기 기술한 바와 같이 배정분 중 약 10% 규모에 대해 청약에 참여할 예정이며, 최대주주는 미청약분의 신주인수권증서 매매를 통해 확보한 자금과 보유현금을 활용해 청약에 참여할 예정입니다.", "rcept_no": "20260623000402", "rcept_dt": "20260623"}, {"basis": "initial", "pct": 10.0, "polarity": "positive", "text": "출처: 당사 제공 당사 최대주주인 김창구 대표이사는 상기 기술한 바와 같이 배정분 중 약 10% 규모에 대해 청약에 참여할 예정이며, 최대주주는 미청약분의 신주인수권증서 매매를 통해 확보한 자금과 보유현금을 활용해 청약에 참여할 예정입니다. 향후 유상증자 진행 과정에서 당사의 주가가 상승하더라도「(舊) 유가증권 발행 및 공시 등에 관한 규정」에 따라 1차 발행가액 대비 확정 발행가액이 상승할 가능성이 제한적으로 발행가격 상승에 따른", "rcept_no": "20260623000402", "rcept_dt": "20260623"}], "text": "268,385 14.00% - - - - - - - 주) 최대주주 및 특수관계인의 주식수는 주식매수선택권 행사 등으로 변동될 수 있습니다. 출처: 당사 제공 당사 최대주주인 김창구 대표이사는 상기 기술한 바와 같이 배정분 중 약 10% 규모에 대해 청약에 참여할 예정이며, 최대주주는 미청약분의 신주인수권증서 매매를 통해 확보한 자금과 보유현금을 활용해 청약에 참여할 예정입니다.", "rcept_no": "20260623000402", "rcept_dt": "20260623"}}, "discount_checked": true, "major_holder_checked": true, "major_holder_parser": 6}','[]');
INSERT INTO "schedule_versions" VALUES('20260821000673',48,'2026-09-26T01:14:21+09:00','2026-09-09',NULL,NULL,NULL,NULL,'2026-10-19','2026-10-20','2026-10-27',NULL,4915,NULL,'{"source": "estkRs", "general": {"rcept_no": "20260821000673", "corp_cls": "K", "corp_code": "00230814", "corp_name": "휴림에이텍", "sbd": "2026년 10월 19일 ~ 2026년 10월 20일", "pymd": "2026년 10월 27일", "sband": "2026년 10월 21일", "asand": "2026년 10월 26일", "asstd": "2026년 09월 09일", "exstk": "-", "exprc": "-", "expd": "-", "rpt_rcpn": "20260821000457"}, "facts": {"underwriting": "잔액인수", "discount": 0.25, "major_holder": {"level": "partial", "pct": 25.0, "initial_pct": 25.0, "held_pct": null, "conflict": false, "evidence": [{"basis": "initial", "pct": 25.0, "polarity": "positive", "text": "당사 최대주주는 증권신고서 제출일 현재 청약금액 기준 20억원에 해당되는 금액을 참여할 예정입니다. 이는 증권신고서 제출일 현재 기준 배정분의 약 25%에 해당되는 청약률입니다.", "rcept_no": "20260821000673", "rcept_dt": "20260821"}, {"basis": "initial", "pct": 25.0, "polarity": "positive", "text": "최대주주는 금번 유상증자 총 6,000,000주 중 1,544,003주를 배정받을 예정입니다. 이에 당사의 최대주주는 20억원 규모로 청약에 참여할 예정이며, 이는 증권신고서 제출일 현재 기준 배정분의 약 25% 수준에 해당되는 청약률입니다.", "rcept_no": "20260821000673", "rcept_dt": "20260821"}, {"basis": "initial", "pct": 25.0, "polarity": "positive", "text": "이에 당사의 최대주주는 20억원 규모로 청약에 참여할 예정이며, 이는 증권신고서 제출일 현재 기준 배정분의 약 25% 수준에 해당되는 청약률입니다. 당사의 최대주주가 위와 같이 20억원을 청약할 경우, 당사의 최대주주 지분율은 25.60%에서 18.41%로 7.19%p 하락할 수 있습니다.", "rcept_no": "20260821000673", "rcept_dt": "20260821"}, {"basis": "none", "pct": 0.0, "polarity": "negative", "text": "[최대주주 및 특수관계인 지분율 현황] (기준일: 증권신고서 제출 전일) (단위: 주, %) 성 명 관 계 주식의종류 소유주식수 및 지분율 비고 주식수 지분율 휴림로봇(주) 최대주주 보통주 2,557,977 25.60 - 합 계 보통주 2,557,977 25.60 - 출처: 당사 제시 주) 최대주주 소유주식수 현황은 2026년 05월 27일 완료 예정인 10:1 무상감자가 반영된 수치입니다. [최대주주 및 특수관계인 증자 후 지분변동 현황] (기준일 : 증권신고서 제출 전일) (단위: 주, %) 성명 증자 전 증자 후 증자 후 미참여 최대주주 20억원 참여 주식수 지분율 배정주식수 주식수 지분율 주식수 지분율 휴림로봇(주) 2,557,977 25.60 1,544,003 2,557,977 16.00 2,943,977 18.41 출처: 당사 제시 주1) 구주주배정비율 : 보통주 1주당 0.6040604946주 주2) 당사의 최대주주는 20억원 규모로 청약에 참여할 예정이며, 이는 증권신고서 제출일 현재 기준 배정분의 25% 수준에 해당되는 청약률입니다.", "rcept_no": "20260821000673", "rcept_dt": "20260821"}, {"basis": "initial", "pct": 25.0, "polarity": "positive", "text": "0 2,943,977 18.41 출처: 당사 제시 주1) 구주주배정비율 : 보통주 1주당 0.6040604946주 주2) 당사의 최대주주는 20억원 규모로 청약에 참여할 예정이며, 이는 증권신고서 제출일 현재 기준 배정분의 25% 수준에 해당되는 청약률입니다.", "rcept_no": "20260821000673", "rcept_dt": "20260821"}, {"basis": "none", "pct": 0.0, "polarity": "negative", "text": "[최대주주 및 특수관계인 증자 후 지분변동 현황] (기준일 : 증권신고서 제출 전일) (단위: 주, %) 성명 증자 전 증자 후 증자 후 미참여 최대주주 20억원 참여 주식수 지분율 배정주식수 주식수 지분율 주식수 지분율 휴림로봇(주) 2,557,977 25.60 1,544,003 2,557,977 16.00 2,943,977 18.41 출처: 당사 제시 주1) 구주주배정비율 : 보통주 1주당 0.6040604946주 주2) 당사의 최대주주는 20억원 규모로 청약에 참여할 예정이며, 이는 증권신고서 제출일 현재 기준 배정분의 25% 수준에 해당되는 청약률입니다. 다만, 상기 배정분에 대한 청약 참여율은 향후 주가 추이에 따라 변동될 수 있습니다, 즉, 발행가액 산정 시기 당사의 주가가 급등하여 확정 발행가액이 증권신고서 제출일 예정발행가액 보다 증가할 경우, 최대주주 배정분에 대한 청약률이 하락할 수 있습니다.", "rcept_no": "20260821000673", "rcept_dt": "20260821"}, {"basis": "initial", "pct": 25.0, "polarity": "positive", "text": "0 2,943,977 18.41 출처: 당사 제시 주1) 구주주배정비율 : 보통주 1주당 0.6040604946주 주2) 당사의 최대주주는 20억원 규모로 청약에 참여할 예정이며, 이는 증권신고서 제출일 현재 기준 배정분의 25% 수준에 해당되는 청약률입니다. 다만, 상기 배정분에 대한 청약 참여율은 향후 주가 추이에 따라 변동될 수 있습니다, 즉, 발행가액 산정 시기 당사의 주가가 급등하여 확정 발행가액이 증권신고서 제출일 예정발행가액 보다 증가할 경우, 최대주주 배정분에 대한 청약률이 하락할 수 있습니다.", "rcept_no": "20260821000673", "rcept_dt": "20260821"}, {"basis": "unknown", "pct": null, "polarity": "unknown", "text": "최대주주인 휴림로봇은 금번 유상증자에 약 20억원 규모로 참여할 예정입니다. 해당 참여 규모는 휴림로봇의 자금수지와 계열사별 지배력 유지 필요성 등을 고려한 현실적인 자금배분 결과이며, 증권신고서 제출일 현재 약 20억원을 초과하는 추가 청약 또는 별도의 자금지원 계획은 확정된 바 없습니다.", "rcept_no": "20260821000673", "rcept_dt": "20260821"}], "text": "당사 최대주주는 증권신고서 제출일 현재 청약금액 기준 20억원에 해당되는 금액을 참여할 예정입니다. 이는 증권신고서 제출일 현재 기준 배정분의 약 25%에 해당되는 청약률입니다.", "rcept_no": "20260821000673", "rcept_dt": "20260821"}}, "discount_checked": true, "major_holder_checked": true, "major_holder_parser": 6}','[]');
INSERT INTO "schedule_versions" VALUES('20260910000583',56,'2026-09-26T01:14:27+09:00','2026-10-01',NULL,NULL,NULL,NULL,'2026-11-09','2026-11-10','2026-11-17',NULL,5030,NULL,'{"source": "estkRs", "general": {"rcept_no": "20260910000583", "corp_cls": "K", "corp_code": "01359815", "corp_name": "한울반도체", "sbd": "2026년 11월 09일 ~ 2026년 11월 10일", "pymd": "2026년 11월 17일", "sband": "2026년 11월 11일", "asand": "2026년 11월 16일", "asstd": "2026년 10월 01일", "exstk": "-", "exprc": "-", "expd": "-", "rpt_rcpn": "20260901000301"}, "facts": {"underwriting": "잔액인수", "discount": 0.25, "major_holder": {"level": "full", "pct": 100.0, "initial_pct": 100.0, "held_pct": null, "text": " 등 주가에도 부정적인 영향을 미칠 수 있습니다. 당사 발행주식총수의 5% 이상 지분율을 보유한 주주는 최대주주 외 특수관계인 외 존재하지 않으며, 최대주주가 계획 중인 청약을 완료할 시 유상증자 후 최대주주 및 특수관계인 지분율 합계는 2 5.36 %로 예상됩니다. 잔여 지분율 7 4.64 %는 자기주식 및 소액주주들에게 분산되어 있어 최대주주의 변경 가능성은 제한적일 것으로 판단하고 있습"}}, "discount_checked": true, "major_holder_checked": true, "major_holder_parser": 3}','[]');
INSERT INTO "schedule_versions" VALUES('20260619000631',58,'2026-09-26T01:14:28+09:00','2026-07-08',NULL,NULL,NULL,NULL,'2026-08-13','2026-08-14','2026-08-24',NULL,2110,NULL,'{"source": "estkRs", "general": {"rcept_no": "20260619000631", "corp_cls": "K", "corp_code": "01593668", "corp_name": "센서뷰", "sbd": "2026년 08월 13일 ~ 2026년 08월 14일", "pymd": "2026년 08월 24일", "sband": "2026년 08월 18일", "asand": "2026년 08월 24일", "asstd": "2026년 07월 08일", "exstk": "-", "exprc": "-", "expd": "-", "rpt_rcpn": "20260619000576"}, "facts": {"underwriting": "잔액인수", "discount": 0.25, "major_holder": {"level": "unknown", "initial_pct": null, "held_pct": 50.0, "conflict": true, "evidence": [{"basis": "initial", "pct": 25.0, "polarity": "positive", "text": "최대주주 청약 참여 등에 따른 지분율 변동 위험 당사의 최대주주, 특수관계인은 금번 주주배정 후 실권주 일반공모 유상증자에 배정물량에 대해 신주배정기준일 이후에 보호예수가 설정되지 않은 보유주식을 25% 수준으로 처분하고 처분대금 , 신주인수권증서 처분대금 과 그 외 개인자금을 이용하여 배정물량의 50% 수준으로 청약할 계획을 가지고 있습니다. 만약 당사의 최대주주 및 특수관계인인 김병남, 강경일의 계획대로 청약이 이루어진다면 당사 최대주주, 특수관계인의 지분율 합계는 11.48%에서 9.73%로 1.75%p 감소할 것으로 예상됩니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "held", "pct": 50.0, "polarity": "positive", "text": "최대주주 청약 참여 등에 따른 지분율 변동 위험 당사의 최대주주, 특수관계인은 금번 주주배정 후 실권주 일반공모 유상증자에 배정물량에 대해 신주배정기준일 이후에 보호예수가 설정되지 않은 보유주식을 25% 수준으로 처분하고 처분대금 , 신주인수권증서 처분대금 과 그 외 개인자금을 이용하여 배정물량의 50% 수준으로 청약할 계획을 가지고 있습니다. 만약 당사의 최대주주 및 특수관계인인 김병남, 강경일의 계획대로 청약이 이루어진다면 당사 최대주주, 특수관계인의 지분율 합계는 11.48%에서 9.73%로 1.75%p 감소할 것으로 예상됩니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "initial", "pct": 50.0, "polarity": "positive", "text": "[유상증자 후 지분율 변동 시뮬레이션] (단위: 주, 백만원) 주주명 관계 유상증자 전 (공시서류 제출일 전일 기준) 유상증자 후 (최대주주 및 특수관계인,주요주주 미청약 가정 시) 유상증자 후 (최대주주 및 특수관계인,주요주주 50% 청약 가정 시) 유상증자 후(최대주주 및 특수관계인,주요주주 100% 청약 가정 시) 유상증자 후(최대주주 및 특수관계인의 청약계획 반영 시) (주3) 배정주식수 및 배정금액(예정발행가액 기준) 주식수 지분율(%) 주식수 지분율(%) 주식수 지분율(%) 주식수 지분율(%) 주식수 지분율(%) 배정주식수 배정금액 김병남 최대주주 3,913,128 7.57% 3,913,128 5.54% 4,631,048 6.56% 5,348,968 7.57% 4,529,455 6.41% 1,4", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "unknown", "pct": 50.0, "polarity": "unknown", "text": "주2) 최대주주 및 특수관계인의 미청약 주식은 기타주주가 모두 청약하여 인수하는 것을 가정하였습니다. 주3) 최대주주인 김병남과 특수관계인인 강경일은 보호예수가 설정되지 않은 보유주식의 25%를 처분한 뒤 배정물량의 50%에 대해 청약하는 것으로 가정하였으며, 그 외 집행임원 및 감사는 배정물량의 50%만 참여하는 것을 가정하였습니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "unknown", "pct": 50.0, "polarity": "unknown", "text": "수하는 것을 가정하였습니다. 주3) 최대주주인 김병남과 특수관계인인 강경일은 보호예수가 설정되지 않은 보유주식의 25%를 처분한 뒤 배정물량의 50%에 대해 청약하는 것으로 가정하였으며, 그 외 집행임원 및 감사는 배정물량의 50%만 참여하는 것을 가정하였습니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "unknown", "pct": 50.0, "polarity": "unknown", "text": "주3) 최대주주인 김병남과 특수관계인인 강경일은 보호예수가 설정되지 않은 보유주식의 25%를 처분한 뒤 배정물량의 50%에 대해 청약하는 것으로 가정하였으며, 그 외 집행임원 및 감사는 배정물량의 50%만 참여하는 것을 가정하였습니다. 당사의 최대주주인 김병남과 집행임원인 강경일이 보유한 보통주 중 일부는 기업공개 당시 3년간의 보호예수가 설정되어 있습니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "none", "pct": 0.0, "polarity": "negative", "text": "당사의 최대주주 및 특수관계인들이 금번 주주배정 후 실권주 일반공모 유상증자에 참여하지 않을 경우, 지분율 합계는 11.48%에서 8.40%로 3.08%p 감소할 것으로 예상됩니다. 또한 금번 주주배정 후 실권주 일반공모 유상증자에 배정물량의 50%만 참여하는 경우 당사 최대주주, 특수관계인의 지분율 합계는 11.48%에서 9.94%로 1.54%p 감소할 것으로 예상되며, 100% 참여한다면 11.48%를 유지할 것으로 예상됩니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "initial", "pct": 50.0, "polarity": "positive", "text": "당사의 최대주주 및 특수관계인들이 금번 주주배정 후 실권주 일반공모 유상증자에 참여하지 않을 경우, 지분율 합계는 11.48%에서 8.40%로 3.08%p 감소할 것으로 예상됩니다. 또한 금번 주주배정 후 실권주 일반공모 유상증자에 배정물량의 50%만 참여하는 경우 당사 최대주주, 특수관계인의 지분율 합계는 11.48%에서 9.94%로 1.54%p 감소할 것으로 예상되며, 100% 참여한다면 11.48%를 유지할 것으로 예상됩니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "initial", "pct": 50.0, "polarity": "positive", "text": "또한 금번 주주배정 후 실권주 일반공모 유상증자에 배정물량의 50%만 참여하는 경우 당사 최대주주, 특수관계인의 지분율 합계는 11.48%에서 9.94%로 1.54%p 감소할 것으로 예상되며, 100% 참여한다면 11.48%를 유지할 것으로 예상됩니다. 추가적으로 당사의 최대주주인 김병남과 특수관계인인 강경일이 계획하고 있는대로 보호예수가 설정되지 않은 주식의 25%를 신주배정기준일 이후 처분", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "initial", "pct": 50.0, "polarity": "positive", "text": "4%p 감소할 것으로 예상되며, 100% 참여한다면 11.48%를 유지할 것으로 예상됩니다. 추가적으로 당사의 최대주주인 김병남과 특수관계인인 강경일이 계획하고 있는대로 보호예수가 설정되지 않은 주식의 25%를 신주배정기준일 이후 처분한 뒤 배정물량의 50%에 대해 청약을 한다는 가정 하에서는 당사 최대주주, 특수관계인의 지분율 합계는 11.48%에서 9.73%로 1.75%p 감소할 것으로 예상됩니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "initial", "pct": 50.0, "polarity": "positive", "text": "추가적으로 당사의 최대주주인 김병남과 특수관계인인 강경일이 계획하고 있는대로 보호예수가 설정되지 않은 주식의 25%를 신주배정기준일 이후 처분한 뒤 배정물량의 50%에 대해 청약을 한다는 가정 하에서는 당사 최대주주, 특수관계인의 지분율 합계는 11.48%에서 9.73%로 1.75%p 감소할 것으로 예상됩니다. 당사의 최대주주 및 특수관계인들을 제외하고는 5%이상 주주가 존재하지는 않습니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "initial", "pct": 25.0, "polarity": "positive", "text": "당사의 최대주주, 특수관계인은 금번 주주배정 후 실권주 일반공모 유상증자에 배정물량에 대해 신주배정기준일 이후에 보호예수가 설정되지 않은 보유주식을 25% 수준으로 처분하고 처분대금 , 신주인수권증서 처분대금 과 그 외 개인자금을 이용하여 배정물량의 50% 수준으로 청약할 계획을 가지고 있습니다. 만약 당사의 최대주주 및 특수관계인인 김병남, 강경일의 계획대로 청약이 이루어진다면 당사 최대주주, 특수관계인의 지분율 합계는 11.48%에서 9.73%로 1.75%p 감소할 것으로 예상됩니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "held", "pct": 50.0, "polarity": "positive", "text": "당사의 최대주주, 특수관계인은 금번 주주배정 후 실권주 일반공모 유상증자에 배정물량에 대해 신주배정기준일 이후에 보호예수가 설정되지 않은 보유주식을 25% 수준으로 처분하고 처분대금 , 신주인수권증서 처분대금 과 그 외 개인자금을 이용하여 배정물량의 50% 수준으로 청약할 계획을 가지고 있습니다. 만약 당사의 최대주주 및 특수관계인인 김병남, 강경일의 계획대로 청약이 이루어진다면 당사 최대주주, 특수관계인의 지분율 합계는 11.48%에서 9.73%로 1.75%p 감소할 것으로 예상됩니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "initial", "pct": 25.0, "polarity": "positive", "text": "최대주주 청약 참여 등에 따른 지분율 변동 위험 당사의 최대주주, 특수관계인은 금번 주주배정 후 실권주 일반공모 유상증자에 배정물량에 대해 신주배정기준일 이후에 보호예수가 설정되지 않은 보유주식을 25% 수준으로 처분하고 처분대금 , 신주인수권증서 처분대금 과 그 외 개인자금을 이용하여 배정물량의 50% 수준으로 청약할 계획을 가지고 있습니다. 만약 당사의 최대주주 및 특수관계인인 김병남, 강경일의 계획대로 청약이 이루어진다면 당사 최대주주, 특수관계인의 지분율 합계는 11.49% 에서 9.74% 로 1.75%p 감소할 것으로 예상됩니다.", "rcept_no": "20260619000631", "rcept_dt": "20260619"}, {"basis": "held", "pct": 50.0, "polarity": 